-- Caridad y Formación pasan del texto de partida a una página por bloques.
--
-- Se reparte lo que ya decían (qué se hace, el voluntariado, a quién va
-- dirigido) en bloques: tarjetas de lo que se hace, una cita del Evangelio,
-- preguntas frecuentes y la llamada a escribir. No se añaden proyectos, cifras
-- ni cuentas que el Grupo no haya dado; lo que sí se añade es comprobable: que
-- la parroquia tiene Cáritas y catequesis, y el horario de su despacho.
--
-- Solo se sustituye la página que sigue con el texto de partida: si alguien ya
-- la ha editado en el CMS, se queda como está.

UPDATE `ContenidoPagina` SET `datos` = '{"cabecera":{"titulo":"Caridad","subtitulo":"Mirar con los ojos de la Virgen a quienes hoy están sin amparo.","foto":"","fotoAlt":""},"bloques":[{"tipo":"texto","titulo":"","html":"<p>La caridad es uno de los fines del Grupo Parroquial y, para una corporación que lleva el nombre de los <strong>Desamparados</strong>, casi una obligación. Buscamos ser signo de la misericordia de Dios con quienes viven en soledad, enfermedad o exclusión.</p><p>No lo hacemos solos: lo hacemos desde la parroquia, junto a quienes ya trabajan en el barrio, y con lo que cada hermano aporta de su tiempo y de su bolsillo.</p>"},{"tipo":"cita","titulo":"","presentacion":{"estilo":"franja","alineacion":"centro"},"texto":"Cada vez que lo hicisteis con uno de estos, mis hermanos más pequeños, conmigo lo hicisteis.","autor":"Jesús","fuente":"Evangelio según san Mateo, 25, 40"},{"tipo":"tarjetas","titulo":"Qué hacemos","presentacion":{"columnas":"2","estilo":"contorno","orientacion":"horizontal","alineacion":"izquierda"},"tarjetas":[{"titulo":"Alimentos","descripcion":"Recogemos y repartimos alimentos para familias que pasan por un mal momento.","enlace":"","icono":"manos"},{"titulo":"Familias en dificultad","descripcion":"Acompañamos a familias del barrio con necesidades concretas, con discreción y sin preguntas de más.","enlace":"","icono":"grupo"},{"titulo":"Enfermos y mayores","descripcion":"Visitamos a enfermos y a personas mayores que viven solas: a veces lo que más falta es compañía.","enlace":"","icono":"corazon"},{"titulo":"Con otras entidades","descripcion":"Colaboramos con Cáritas parroquial y con otras entidades sociales de Málaga para llegar más lejos.","enlace":"","icono":"iglesia"}]},{"tipo":"texto","titulo":"Voluntarios","html":"<p>La caridad del Grupo no se entiende sin los hermanos que dedican parte de su tiempo al servicio de los demás. No hace falta experiencia ni mucho tiempo: basta con ganas y un par de horas cuando se pueda.</p><p>Si quieres sumarte, escríbenos y te contamos en qué andamos ahora.</p>"},{"tipo":"preguntas","titulo":"Preguntas frecuentes","preguntas":[{"pregunta":"¿Tengo que ser hermano para ayudar?","respuesta":"No. Cualquiera puede echar una mano o colaborar con un donativo. Escríbenos y te decimos cómo."},{"pregunta":"¿Cómo hago un donativo?","respuesta":"Escríbenos desde la página de contacto y te indicamos cómo hacerlo llegar y a qué se destina."},{"pregunta":"Necesito ayuda, ¿a quién acudo?","respuesta":"Puedes acudir a Cáritas parroquial de Santa María Goretti. Pregunta en el despacho parroquial (martes y viernes, de 18:00 a 20:00) o escríbenos y te orientamos."}]},{"tipo":"llamada","titulo":"","texto":"¿Quieres echar una mano o colaborar con un donativo?","boton":"Escríbenos","enlace":"/contacto"}]}'
WHERE `slug` = 'caridad' AND `datos` LIKE '%La caridad constituye uno de los fines fundamentales de nuestro Grupo Parroquial%';

UPDATE `ContenidoPagina` SET `datos` = '{"cabecera":{"titulo":"Formación","subtitulo":"Crecer en la fe para entender lo que celebramos.","foto":"","fotoAlt":""},"bloques":[{"tipo":"texto","titulo":"","html":"<p>La formación es uno de los pilares del Grupo Parroquial. No se trata de acumular conocimientos, sino de ayudar a cada hermano a conocer mejor a Dios, a vivir el Evangelio en lo de cada día y a entender lo que celebramos: por qué rezamos un triduo, qué significa el besamanos o por qué salimos a la calle.</p><p>Todo lo que proponemos está abierto a hermanos, devotos y a cualquiera que quiera acercarse.</p>"},{"tipo":"tarjetas","titulo":"Qué ofrecemos","presentacion":{"columnas":"2","estilo":"contorno","orientacion":"horizontal","alineacion":"izquierda"},"tarjetas":[{"titulo":"Catequesis y charlas","descripcion":"Sesiones durante el curso para profundizar en la fe, la liturgia y la devoción a la Virgen.","enlace":"","icono":"libro"},{"titulo":"Retiros y oración","descripcion":"Momentos para parar, rezar juntos y prepararse para los tiempos fuertes del año.","enlace":"","icono":"sol"},{"titulo":"La espiritualidad de la Pasión","descripcion":"De la mano de los Pasionistas, que nos acompañan en la parroquia, con la Cruz como escuela de amor.","enlace":"","icono":"iglesia"},{"titulo":"Jóvenes y nuevos hermanos","descripcion":"Una atención especial para que conozcan la historia, los fines y las tradiciones del Grupo.","enlace":"","icono":"grupo"}]},{"tipo":"cita","titulo":"","presentacion":{"estilo":"franja","alineacion":"centro"},"texto":"María conservaba todas estas cosas, meditándolas en su corazón.","autor":"","fuente":"Evangelio según san Lucas, 2, 19"},{"tipo":"preguntas","titulo":"Preguntas frecuentes","preguntas":[{"pregunta":"¿Tengo que ser hermano para ir?","respuesta":"No. Las sesiones están abiertas a todos: hermanos, devotos y cualquiera que quiera acercarse."},{"pregunta":"¿Cuándo son las próximas sesiones?","respuesta":"Las anunciamos en la Agenda, con su fecha, hora y lugar. Desde allí puedes añadirlas a tu calendario."},{"pregunta":"¿Preparáis para los sacramentos?","respuesta":"La parroquia de Santa María Goretti tiene catequesis de niños, jóvenes y adultos y prepara bautizos y bodas. Pregunta en el despacho parroquial, los martes y viernes de 18:00 a 20:00."}]},{"tipo":"botones","titulo":"","presentacion":{"alineacion":"centro"},"botones":[{"texto":"Ver la agenda","enlace":"/agenda","estilo":"principal"},{"texto":"Escríbenos","enlace":"/contacto","estilo":"secundario"}]}]}'
WHERE `slug` = 'formacion' AND `datos` LIKE '%La formación cristiana es uno de los pilares sobre los que se sustenta%';
